function simplifiedFractions(n) {
  function gcd(a, b) {
    while (b !== 0) {
      const rest = a % b;
      a = b;
      b = rest;
    }
    return a;
  }

  const result = [];
  for (let numerator = 1; numerator < n; numerator++) {
    for (let denominator = numerator + 1; denominator <= n; denominator++) {
      if (gcd(numerator, denominator) === 1) {
        result.push(`${numerator}/${denominator}`);
      }
    }
  }
  return result;
}

