function simplifiedFractions(n) {
  const seen = new Set();
  for (let bottom = 2; bottom <= n; bottom++) {
    for (let top = 1; top < bottom; top++) {
      let a = top, b = bottom;
      for (let d = 2; d <= a; d++) {
        while (a % d === 0 && b % d === 0) { a /= d; b /= d; }
      }
      seen.add(a + '/' + b);
    }
  }
  return [...seen];
}

